// `Namespace N { Function F }` is `N_F`, and the flatten map remembers `N::F`.

/// @custom
void Common_ApplyTint(float3 color, float3 tint, out float3 result)
{
        result = color * tint;
    }

/// @custom
void Common_Twice(float value, out float result)
{
        result = Common_Half(value) * 4.0;
    }

/// @custom
void Common_Half(float value, out float result)
{
        result = value * 0.5;
    }
